WITH p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),car AS (SELECT REPLACE(a.id_imovel,'-','') id_car_norm,a.id_imovel,a.id_municipio,a.area FROM `basedosdados.br_sfb_sicar.area_imovel` a WHERE a.id_municipio='2929701' AND a.data_extracao>=DATE '2026-06-02' AND a.data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(a.id_imovel,'-','') ORDER BY a.data_extracao DESC)=1),l AS (SELECT p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,p.id_car_norm,c.area FROM p JOIN car c USING(id_car_norm)),m AS (SELECT ano_emissao,id_referencia_bacen,numero_ordem FROM l GROUP BY 1,2,3 HAVING COUNTIF(area<0.1)>0 AND COUNTIF(area>=1)>0) SELECT COUNT(*) operacoes_mistas_do_focal,COUNT(DISTINCT m.id_referencia_bacen) referencias_mistas_do_focal FROM m JOIN l USING(ano_emissao,id_referencia_bacen,numero_ordem) WHERE l.id_car_norm=REPLACE('BA-2929701-3438EBE3EC1C4160B13A7DC99112E048','-','')